WITH op AS (SELECT id FROM operators WHERE slug='bingo-auctions'),
sold AS (SELECT il.invoice_id, il.lot_id, il.winning_bid_cents, il.refunded_at, il.picked_up_at, i.created_at icr, l.category, l.lotted_by_worker, l.intake_bin_id, l.relisted_from_lot_id, l.removal_kind, l.flagged_for_disposal, w.name wh
  FROM invoice_lots il JOIN invoices i ON i.id=il.invoice_id JOIN lots l ON l.id=il.lot_id LEFT JOIN auctions a ON a.id=l.auction_id LEFT JOIN warehouses w ON w.id=a.warehouse_id, op
  WHERE i.operator_id=op.id AND i.created_at>=now()-interval '84 days' AND i.status::text <> 'canceled'),
au AS (SELECT DISTINCT ON (target_id, after_state->>'lot_id') target_id, (after_state->>'lot_id')::uuid lot_id, after_state->>'sub_reason' sr, coalesce(after_state->>'reason_note','') note, actor_user_id FROM operator_audit_log, op WHERE operator_audit_log.operator_id=op.id AND action_type='invoice.refund_item' AND created_at>=now()-interval '90 days' ORDER BY target_id, after_state->>'lot_id', created_at),
plo AS (SELECT DISTINCT lot_id FROM pickup_lot_outcomes WHERE outcome='missing'),
r AS (SELECT s.*, au.sr, au.note, au.actor_user_id, (plo.lot_id IS NOT NULL) counter_missing FROM sold s LEFT JOIN au ON au.target_id=s.invoice_id AND au.lot_id=s.lot_id LEFT JOIN plo ON plo.lot_id=s.lot_id WHERE s.refunded_at IS NOT NULL AND s.picked_up_at IS NULL)
SELECT
(SELECT json_build_object('lines', count(*), 'hammer_c', sum(winning_bid_cents), 'with_refund_item_audit', count(sr), 'counter_marked_missing', count(*) FILTER (WHERE counter_missing), 'lot_destroyed', count(*) FILTER (WHERE removal_kind='destroyed'), 'lot_missing_kind', count(*) FILTER (WHERE removal_kind='missing'), 'disposal_flag', count(*) FILTER (WHERE flagged_for_disposal), 'note_nonempty', count(*) FILTER (WHERE note<>''), 'no_shelf', count(*) FILTER (WHERE intake_bin_id IS NULL), 'relisted_lot', count(*) FILTER (WHERE relisted_from_lot_id IS NOT NULL)) FROM r) tot,
(SELECT json_agg(x) FROM (SELECT coalesce(sr,'(no item audit)') sr, counter_missing, count(*) n, sum(winning_bid_cents) c FROM r GROUP BY 1,2 ORDER BY 3 DESC) x) by_reason,
(SELECT json_agg(x) FROM (SELECT coalesce(wh,'?') wh, count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) refunded, count(*) sold, round(count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL)::numeric/count(*),3) rate FROM sold GROUP BY 1 ORDER BY 2 DESC) x) by_wh,
(SELECT json_agg(x) FROM (SELECT coalesce(category,'none') cat, count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) refunded, count(*) sold, round(count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL)::numeric/count(*),3) rate, sum(winning_bid_cents) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) c FROM sold GROUP BY 1 HAVING count(*)>=100 ORDER BY 2 DESC LIMIT 15) x) by_cat,
(SELECT json_agg(x) FROM (SELECT coalesce(left(md5(lotted_by_worker::text),6),'(no worker)') lotter, count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) refunded, count(*) sold, round(count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL)::numeric/count(*),3) rate FROM sold GROUP BY 1 HAVING count(*)>=100 ORDER BY 4 DESC) x) by_lotter,
(SELECT json_agg(x) FROM (SELECT coalesce(left(md5(actor_user_id::text),6),'(no audit)') refunder, count(*) n, count(*) FILTER (WHERE sr='wrong_item') wrong_missing, count(*) FILTER (WHERE sr='defective_item') defective, count(*) FILTER (WHERE sr='damaged_in_transit') damaged, count(*) FILTER (WHERE sr='other') other FROM r GROUP BY 1 ORDER BY 2 DESC) x) by_refunder,
(SELECT json_agg(x) FROM (SELECT (intake_bin_id IS NOT NULL) shelved, (relisted_from_lot_id IS NOT NULL) relisted, count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) refunded, count(*) sold, round(count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL)::numeric/count(*),3) rate FROM sold GROUP BY 1,2) x) by_shelf_relist,
(SELECT json_agg(x) FROM (SELECT CASE WHEN h<24 THEN 'a <1d' WHEN h<72 THEN 'b 1-3d' WHEN h<168 THEN 'c 3-7d' ELSE 'd 7d+' END b, count(*) n FROM (SELECT extract(epoch FROM refunded_at-icr)/3600 h FROM r) z GROUP BY 1 ORDER BY 1) x) by_timing,
(SELECT json_agg(x) FROM (SELECT date_trunc('week', icr AT TIME ZONE 'America/Chicago')::date wk, count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) refunded, count(*) sold FROM sold GROUP BY 1 ORDER BY 1) x) by_week
